class Solution:
    def checkDistances(self, s: str, distance: List[int]) -> bool:
        first = {}
        for i, c in enumerate(s):
            if c in first:
                if i - first[c] - 1 != distance[ord(c) - 97]:
                    return False
            else:
                first[c] = i
        return True

