class Solution {
public:
    bool checkDistances(string s, vector<int>& distance) {
        int first[26]; fill(first, first+26, -1);
        for (int i = 0; i < (int)s.size(); i++) {
            int c = s[i] - 'a';
            if (first[c] < 0) first[c] = i;
            else if (i - first[c] - 1 != distance[c]) return false;
        }
        return true;
    }
};

