class Solution:
    def checkDistances(self, s: str, distance: List[int]) -> bool:
        first, last = {}, {}
        for i, c in enumerate(s):
            first.setdefault(c, i)
            last[c] = i
        return all(last[c] - first[c] - 1 == distance[ord(c) - 97] for c in first)

